// Record-based checks.
// Cases covered here: 1a (2+ refund requests from the same customer, any
// request type), 1b (refund spanning 2+ transactions or 2+ subscriptions,
// refund requests only), the cross-ticket half of case 2 (a refund request
// after an earlier ticket was marked Rejection Complaint = yes) and case 6
// (a chargeback or dispute on record, refund requests only).
// Case 7b is NOT here - it is in-ticket only and lives in the 2nd message
// eligibility check. Neither is the same-ticket half of case 2 - it lives in
// the 2nd message trigger, after Is refund request. Case 6 on replies also
// lives in the 2nd message trigger, after DEV bot/search1.
//
// Everything is computed from data already in hand: Zendesk ticket history for
// the requester, and the payments bot/search arrays passed in by the caller.
// No AI, no payments call of its own.

const input = $('When Executed by Another Workflow').first().json;
const cfg = $('Get Project Config').first().json || {};
const search = $('RB: Requester ticket history').first().json || {};

const ticketId = Number(input.ticket_id);

// --- config, with safe defaults -------------------------------------------
// enabled/enforce are fail-CLOSED on enabled (a project that has not been
// configured does not run the checks) and fail-SAFE on enforce (an unconfigured
// project tags but never blocks).
function truthy(v) {
  return v === true || v === 1 || v === 'true' || v === '1' || v === 'yes';
}
const enabled = truthy(cfg.record_checks_enabled);
const enforce = truthy(cfg.record_checks_enforce);
const tagPrefix = String(cfg.record_refund_tag_prefix || 'refund').toLowerCase();

// Case 6 has its own pair of switches (decision 2026-10-14), independent of
// record_checks_enabled / record_checks_enforce, so it can be dropped to
// tag-only or switched off without touching 1a / 1b / 2.
const case6Enabled = truthy(cfg.record_case6_enabled);
const case6Enforce = truthy(cfg.record_case6_enforce);

// --- request type ----------------------------------------------------------
// Classifier token passed in by the main flow: r = refund, c = cancellation.
// other_auto never reaches these checks. If the caller did not pass it, the
// request is treated as a refund - that was the behaviour before the input
// existed, and over-flagging is the safer failure for a flag check.
const requestType = String(input.request_type == null ? '' : input.request_type).trim().toLowerCase();
const isRefundRequest = requestType === '' || requestType === 'r';

// --- case 1a: prior refund requests from the same requester ----------------
// Any tag beginning with the configured prefix marks a prior ticket as a refund
// request. Measured on Personality 2026-09: refund_auto, refund__within_30_days__monthly,
// refund__30_day_policy__last_charge_only and friends all share the prefix.
//
// The CURRENT ticket is excluded. The search returns it too (it is an open
// ticket for this requester), and counting it would make every refund request
// look like a repeat.
const results = Array.isArray(search.results) ? search.results : [];
const priorTickets = results.filter(function (t) {
  return t && t.id !== ticketId;
});

const priorRefundTickets = priorTickets.filter(function (t) {
  const tags = Array.isArray(t.tags) ? t.tags : [];
  return tags.some(function (tag) {
    return String(tag).toLowerCase().indexOf(tagPrefix) === 0;
  });
});

// current request + 1 prior = 2 refund requests, which is the case threshold
const case1a = priorRefundTickets.length >= 1;

// --- case 1b: refund spanning multiple transactions or subscriptions -------
// transactions[] is the 30-day refundable window by design - the payments API
// deliberately does not return older ones because they cannot be refunded.
// So this fires on 2+ refundable charges inside that window, which is the
// agreed scope. refundedTransactions[] is all-time and is reported for context
// but does not itself trip 1b.
function parseArray(raw) {
  if (Array.isArray(raw)) return raw;
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

const transactions = parseArray(input.transactions_json);
const refunded = parseArray(input.refunded_transactions_json);
const chargebacks = parseArray(input.chargeback_transactions_json);

const subIds = [];
transactions.forEach(function (t) {
  const sid = t && (t.subscriptionId || t.subscription_id);
  if (sid && subIds.indexOf(sid) === -1) subIds.push(sid);
});

// Refund requests only, by decision 2026-09-23. A cancellation that touches
// several charges or subscriptions is not a risk in itself.
// The subscription half needs subscriptionId on each transaction. bot/search
// does not return it yet (checked 2026-10-15), so today only the 2+
// transactions half can fire; the subscription half starts working as soon as
// the payments team adds the field, with no change here.
const case1b = isRefundRequest && (transactions.length >= 2 || subIds.length >= 2);

// --- case 2 (cross-ticket): refund requested again after a rejection -------
// An earlier ticket from this requester carries Rejection Complaint = yes (set
// by the Zendesk ticket update request sub-workflow when the rejection macro
// was sent, or by an agent on a manual rejection) and the customer is now
// asking for a refund again. The search results already include each ticket's
// custom_fields, so this costs no extra call. Tickets from before the field
// existed carry no value and are deliberately not considered (2026-09-23).
const rcFieldId = Number(cfg.ticket_field_rejection_complaint);
const rcConfigured = Number.isFinite(rcFieldId) && rcFieldId > 0;
// "Yes" option value from cs_project_config (empty = yes).
const rcYesValue = String(cfg.rejection_complaint_value_yes || 'yes');
const priorRejectedTickets = rcConfigured ? priorTickets.filter(function (t) {
  const fields = Array.isArray(t.custom_fields) ? t.custom_fields : [];
  return fields.some(function (f) {
    return f && Number(f.id) === rcFieldId && f.value === rcYesValue;
  });
}) : [];

const case2 = isRefundRequest && priorRejectedTickets.length >= 1;

// --- case 6: chargeback or dispute on record --------------------------------
// chargebackTransactions[] is all-time and mixes chargebacks and disputes.
// Existence is enough (decision 2026-10-14): the API does not say whether a
// dispute is open, won or lost, and it does not matter for routing.
// Refund requests only - a cancellation request with a chargeback carries on.
const case6 = case6Enabled && isRefundRequest && chargebacks.length >= 1;

function day(iso) {
  return iso ? String(iso).slice(0, 10) : '?';
}
function describeChargeback(c) {
  c = c || {};
  const amount = (c.amount != null ? c.amount : '?') + (c.currency ? ' ' + c.currency : '');
  const provider = c.provider && c.provider.type ? c.provider.type : 'unknown provider';
  return 'recorded ' + day(c.chargebackDate) + ', ' + amount + ' disputed, ' + provider +
    ', ' + (c.type || 'unknown type') + ' charge of ' + day(c.transactionDate);
}

// --- verdict ---------------------------------------------------------------
// Cases 1a / 1b / 2 only count when record_checks_enabled is on; case 6 only
// when record_case6_enabled is on. Each family blocks under its own enforce.
const cases = [];
const tags = [];
const reasons = [];
if (enabled) {
  if (case1a) {
    cases.push('1a'); tags.push('record_case_1a');
    reasons.push('Customer has ' + priorRefundTickets.length + ' previous refund request ticket(s): ' + priorRefundTickets.map(function (t) { return '#' + t.id; }).join(', '));
  }
  if (case1b) {
    cases.push('1b'); tags.push('record_case_1b');
    reasons.push('Refund spans ' + transactions.length + ' refundable transaction(s)' + (subIds.length > 0 ? ' across ' + subIds.length + ' subscription(s)' : '') + ' in the 30 day window');
  }
  if (case2) {
    cases.push('2'); tags.push('record_case_2');
    reasons.push('Customer had a refund rejected on previous ticket(s): ' + priorRejectedTickets.map(function (t) { return '#' + t.id; }).join(', '));
  }
}
const cat1Matched = cases.length > 0;

if (case6) {
  cases.push('6'); tags.push('record_case_6');
  reasons.push('Chargeback or dispute on record (' + chargebacks.length + '): ' + chargebacks.map(describeChargeback).join('; '));
}

const matched = cases.length > 0;
if (matched) tags.push('record_based_flag');

const shouldBlock = (cat1Matched && enforce) || (case6 && case6Enforce);

return [{
  json: {
    rb_enabled: enabled,
    rb_enforce: enforce,
    rb_matched: matched,
    rb_should_block: shouldBlock,
    rb_cases: cases,
    rb_tags: tags,
    rb_reason: reasons.join(' | '),
    rb_case_1a: case1a,
    rb_case_1b: case1b,
    rb_case_2: case2,
    rb_case_6: case6,
    rb_case6_enabled: case6Enabled,
    rb_case6_enforce: case6Enforce,
    rb_request_type: requestType || null,
    rb_prior_ticket_count: priorTickets.length,
    rb_prior_refund_ticket_count: priorRefundTickets.length,
    rb_prior_refund_ticket_ids: priorRefundTickets.map(function (t) { return t.id; }),
    rb_prior_rejected_ticket_ids: priorRejectedTickets.map(function (t) { return t.id; }),
    rb_transaction_count: transactions.length,
    rb_subscription_count: subIds.length,
    rb_refunded_transaction_count: refunded.length,
    rb_chargeback_count: chargebacks.length,
    rb_search_error: search.error ? String(search.error) : null
  }
}];
